                                    num = trigger.num;
                                if (player.storage.daoguishuaju) await player.draw(num + 1);
                                else await player.draw(num);
                                var result = await player
                                    .chooseCard('选择至少一张牌置于牌堆顶或牌堆底', [1, Infinity], true, 'h')
                                    .set('ai', (card) => {
                                        var num = _status.event.numx,
                                            target = _status.event.targetx,
                                            player = _status.event.player;
                                        if (((player.storage.daoguishuaju ? num + 1 : num) > 2 && ui.selected.cards?.length == 1) || ui.selected.cards?.length == num) return 0;
                                        if (get.attitude(player, target) > 0 && target != player) {
                                            return target.getUseValue(card, true, true) + 1;
                                        }
                                        return 0 - get.value(card);
                                    })
                                    .set('numx', num)
                                    .set('targetx', trigger.player)
                                    .set('complexSelect', true);
                                if (!result.bool || !result.cards || !result.cards.length) return;
                                var cards = result.cards;
                                player.storage.daoguishuaju = 0;
                                if (cards.length > num) player.storage.daoguishuaju = 1;
                                if (cards.length < num) player.addTempSkill('daoguishuaju_sub');
                                result = await player
                                    .chooseControl(['牌堆顶', '牌堆底'], true)
                                    .set('choiceList', ['牌堆顶', '牌堆底'])
                                    .set('ai', () => {
                                        if (_status.event.triggerx.bottom || _status.event.triggerx.player == _status.event.player) return 1;
                                        return 0;
                                    })
                                    .set('triggerx', trigger);
