                                                    if (player.storage.dualside[3] == 'gui_heiyansheshou' && get.type2(card) == 'trick' && !player.storage.gui_biaolizhuanhuan) return [0, 0];
                                                    else if (player.storage.dualside[0] == 'gui_heiyimatao' && get.type2(card) == 'basic' && player.storage.gui_biaolizhuanhuan) return [0, -1];
                                                    return;
